# Build lookup dict on import
AIRFOIL_DB = {}
for _r in _DATA:
    _n, _fam, _t, _xt, _cam, _cm, _cl = _r
    AIRFOIL_DB[_n] = {
        'name':_n, 'family':_fam, 't_c':_t, 'x_t_c':_xt,
        'camber':_cam, 'Cm_ac':_cm, 'Cl_max':_cl,
        'Cl_alpha':6.283, 'x_ac_c':0.25,
        'is_riblett':'Riblett' in _fam,
        'is_laminar': any(x in _fam for x in ['Wortmann','Eppler','Selig']),
        'is_estimated':True,
        'description':f'{_n} ({_fam})',
        'notes':'', 'verify':'V',
    }

AIRFOIL_DB['Manual Entry'] = {
    'name':'Manual Entry','family':'','t_c':None,'x_t_c':None,
    'camber':None,'Cm_ac':None,'Cl_max':None,'Cl_alpha':None,
    'x_ac_c':None,'is_riblett':False,'is_laminar':False,
    'is_estimated':False,'description':'Manual / Custom',
    'notes':'Enter all values manually.','verify':'V',}

def get_airfoil(name: str):
    if name in AIRFOIL_DB: return AIRFOIL_DB[name]
    nl = name.lower()
    for k,v in AIRFOIL_DB.items():
        if k.lower() == nl: return v
    return None

def airfoil_names(): return list(AIRFOIL_DB.keys())
def airfoil_families():
    from collections import OrderedDict
    fams = list(dict.fromkeys(v["family"] for v in AIRFOIL_DB.values() if v["family"]))
    return sorted(fams)